-- Roles are seeded explicitly by trusted authenticated user ID; no automatic first-login admin.
CREATE TABLE IF NOT EXISTS service_access_roles (user_id text PRIMARY KEY, role text NOT NULL CHECK (role = 'service_admin'), created_at timestamptz NOT NULL DEFAULT now()); CREATE TABLE IF NOT EXISTS service_dashboard_preferences (user_id text PRIMARY KEY, widgets jsonb NOT NULL CHECK (jsonb_typeof(widgets) = 'array'), version integer NOT NULL DEFAULT 1, updated_at timestamptz NOT NULL DEFAULT now());

CREATE OR REPLACE FUNCTION protect_reviewed_service_job() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN IF OLD.data->>'status' = 'Completed' AND OLD.data ? 'adminReview' AND NEW.data IS DISTINCT FROM OLD.data THEN RAISE EXCEPTION 'Completed jobs are locked after Service Admin review'; END IF; RETURN NEW; END $$; DROP TRIGGER IF EXISTS protect_reviewed_service_job_data ON service_jobs; CREATE TRIGGER protect_reviewed_service_job_data BEFORE UPDATE OF data ON service_jobs FOR EACH ROW EXECUTE FUNCTION protect_reviewed_service_job();
